package run.ikaros.planning; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/v2/planning/important-dates") public class PlanningImportantDateController {private final PlanningImportantDateService s;public PlanningImportantDateController(PlanningImportantDateService s){this.s=s;}@PostMapping public Mono<PlanningImportantDateView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@Valid@RequestBody CreatePlanningImportantDateRequest r){return s.create(o,r);}@GetMapping public Flux<PlanningImportantDateView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID o){return s.list(o);}@PatchMapping("/{dateId}")public Mono<PlanningImportantDateView> update(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID dateId,@Valid@RequestBody UpdatePlanningImportantDateRequest r){return s.update(o,dateId,r);}@DeleteMapping("/{dateId}")public Mono<PlanningImportantDateView> archive(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID dateId){return s.archive(o,dateId);}}
